import 'package:flutter/material.dart'; import '../../services/auth_service.dart'; import '../../repositories/result_repository.dart'; class ResultsPage extends StatelessWidget { const ResultsPage({super.key}); @override Widget build(BuildContext c){final id=AuthService().currentUser?.uid;if(id==null)return const Scaffold(body:Center(child:Text('سجّل الدخول أولًا')));return Scaffold(appBar:AppBar(title:const Text('نتائجي')),body:StreamBuilder(stream:ResultRepository().byStudent(id),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('لا توجد نتائج بعد'));return ListView(children:s.data!.map((r)=>ListTile(title:Text('الاختبار: ${r.examId}'),subtitle:Text(r.submittedAt.toLocal().toString()),trailing:Text('${r.score.toStringAsFixed(0)}%'))).toList());}));}}